/* @autogenerated */
import type { IParagraphOptions, ParagraphChild } from 'docx';
import { Block, Run } from './document.model';

type Docx = typeof import('docx');

const CODE_FONT = 'Consolas';
/** Sangría por nivel de cita, en twips. */
const QUOTE_INDENT = 567;

/** Bloques a un documento Word (`.docx`). */
export async function writeDocx(blocks: Block[], title = ''): Promise<Blob> {
  const docx = await import('docx');
  const writer = new DocxWriter(docx);
  const children = writer.blocks(blocks);
  const document = new docx.Document({
    title,
    numbering: { config: writer.numbering() },
    styles: { default: { document: { run: { font: 'Calibri', size: 22 } } } },
    sections: [{ children }],
  });
  return docx.Packer.toBlob(document);
}

class DocxWriter {
  /** Cada lista numerada necesita su propia instancia para que vuelva a empezar en 1 (o en su `start`). */
  private readonly ordered: { reference: string; start: number }[] = [];

  constructor(private readonly docx: Docx) {}

  numbering() {
    const { LevelFormat, AlignmentType } = this.docx;
    const levels = (start: number) =>
      Array.from({ length: 6 }, (_, level) => ({
        level,
        format: LevelFormat.DECIMAL,
        text: `%${level + 1}.`,
        start: level === 0 ? start : 1,
        alignment: AlignmentType.START,
        style: { paragraph: { indent: { left: 720 * (level + 1), hanging: 360 } } },
      }));
    return this.ordered.map(({ reference, start }) => ({ reference, levels: levels(start) }));
  }

  blocks(blocks: Block[], quote = 0): any[] {
    return blocks.flatMap((block) => this.block(block, quote));
  }

  private block(block: Block, quote: number): any[] {
    const { Paragraph, HeadingLevel, PageBreak, BorderStyle } = this.docx;
    const indent = quote ? { indent: { left: QUOTE_INDENT * quote } } : {};
    switch (block.kind) {
      case 'heading': {
        const levels = [
          HeadingLevel.HEADING_1,
          HeadingLevel.HEADING_2,
          HeadingLevel.HEADING_3,
          HeadingLevel.HEADING_4,
          HeadingLevel.HEADING_5,
          HeadingLevel.HEADING_6,
        ];
        return [new Paragraph({ heading: levels[block.level - 1], children: this.runs(block.runs), ...indent })];
      }
      case 'paragraph':
        return [new Paragraph({ children: this.runs(block.runs), spacing: { after: 120 }, ...indent })];
      case 'list':
        return this.list(block, 0, quote);
      case 'table':
        return [this.table(block)];
      case 'code':
        return block.text.split('\n').map(
          (line) =>
            new Paragraph({
              children: [new this.docx.TextRun({ text: line || ' ', font: CODE_FONT, size: 20 })],
              shading: { fill: 'F3F3F3' },
              ...indent,
            }),
        );
      case 'quote':
        return this.blocks(block.blocks, quote + 1);
      case 'rule':
        return [
          new Paragraph({
            children: [],
            border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: 'BBBBBB', space: 1 } },
          }),
        ];
      case 'pagebreak':
        return [new Paragraph({ children: [new PageBreak()] })];
    }
  }

  private list(block: Extract<Block, { kind: 'list' }>, level: number, quote: number): any[] {
    const { Paragraph } = this.docx;
    let reference = '';
    if (block.ordered) {
      reference = 'ordered-' + this.ordered.length;
      this.ordered.push({ reference, start: block.start });
    }
    const marker = (): Partial<IParagraphOptions> =>
      block.ordered ? { numbering: { reference, level } } : { bullet: { level } };
    return block.items.flatMap((item) => {
      // El primer párrafo lleva la viñeta; las sublistas bajan un nivel
      let first = true;
      return item.flatMap((child) => {
        if (child.kind === 'list') {
          return this.list(child, level + 1, quote);
        }
        if (child.kind === 'paragraph' && first) {
          first = false;
          return [new Paragraph({ children: this.runs(child.runs), ...marker() })];
        }
        return this.block(child, quote);
      });
    });
  }

  private table(block: Extract<Block, { kind: 'table' }>) {
    const { Table, TableRow, TableCell, Paragraph, WidthType, AlignmentType } = this.docx;
    const alignment = (index: number) =>
      block.align[index] === 'center'
        ? AlignmentType.CENTER
        : block.align[index] === 'right'
          ? AlignmentType.RIGHT
          : AlignmentType.LEFT;
    const row = (cells: Run[][], header: boolean) =>
      new TableRow({
        tableHeader: header,
        children: cells.map(
          (cell, index) =>
            new TableCell({
              shading: header ? { fill: 'EEEEEE' } : undefined,
              children: [
                new Paragraph({
                  alignment: alignment(index),
                  children: this.runs(header ? cell.map((run) => ({ ...run, bold: true })) : cell),
                }),
              ],
            }),
        ),
      });
    return new Table({
      width: { size: 100, type: WidthType.PERCENTAGE },
      rows: [row(block.header, true), ...block.rows.map((cells) => row(cells, false))],
    });
  }

  private runs(runs: Run[]): ParagraphChild[] {
    const { TextRun, ExternalHyperlink } = this.docx;
    return runs.map((run) => {
      if (run.break) {
        return new TextRun({ text: '', break: 1 });
      }
      const text = new TextRun({
        text: run.text,
        bold: run.bold,
        italics: run.italic,
        strike: run.strike,
        font: run.code ? CODE_FONT : undefined,
        style: run.link ? 'Hyperlink' : undefined,
      });
      return run.link ? new ExternalHyperlink({ link: run.link, children: [text] }) : text;
    });
  }
}
